 static class Match { int cut; double error; Match(int c,double e){cut=c;error=e;} double weight(){return cut>0?cut*Math.max(0,21-error):0;} }

 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(0xfff2f5fa);getWindow().setNavigationBarColor(0xfff2f5fa);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);home();}
 int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+0.5f);}
 TextView text(String s,int size,int color){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);return v;}
 Drawable glass(int top,int bottom){int r=dp(28);GradientDrawable base=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{top,bottom});base.setCornerRadius(r);GradientDrawable shine=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0x88ffffff,0x22ffffff,0x00ffffff});shine.setCornerRadius(r);GradientDrawable rim=new GradientDrawable();rim.setColor(0x00000000);rim.setCornerRadius(r);rim.setStroke(dp(1),0xddffffff);GradientDrawable mask=new GradientDrawable();mask.setColor(Color.WHITE);mask.setCornerRadius(r);LayerDrawable layers=new LayerDrawable(new Drawable[]{base,shine,rim});layers.setLayerInset(1,dp(2),dp(2),dp(2),dp(27));return new RippleDrawable(ColorStateList.valueOf(0x33ffffff),layers,mask);}
 void fitSystemBars(View root){root.setOnApplyWindowInsetsListener((v,in)->{int top,bottom;if(Build.VERSION.SDK_INT>=30){android.graphics.Insets a=in.getInsets(WindowInsets.Type.statusBars()|WindowInsets.Type.navigationBars());top=a.top;bottom=a.bottom;}else{top=in.getSystemWindowInsetTop();bottom=in.getSystemWindowInsetBottom();}v.setPadding(dp(20),top+dp(16),dp(20),bottom+dp(38));return in;});root.post(()->root.requestApplyInsets());}
 void home(){
  LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(20),dp(16),dp(20),dp(20));root.setBackgroundColor(0xfff2f5fa);setContentView(root);fitSystemBars(root);
  LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.ic_logo);head.addView(logo,new LinearLayout.LayoutParams(dp(44),dp(44)));LinearLayout title=new LinearLayout(this);title.setOrientation(1);title.setPadding(dp(12),0,0,0);title.addView(text("长图助手",24,0xff172b4d));title.addView(text("本机拼接 · AI 辅助可选",13,0xff718096));head.addView(title);root.addView(head);
  LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(16),dp(14),dp(16),dp(12));GradientDrawable white=new GradientDrawable();white.setColor(Color.WHITE);white.setCornerRadius(dp(22));card.setBackground(white);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.topMargin=dp(16);root.addView(card,cp);
  card.addView(text("把连续截图拼成一张长图",18,0xff172b4d));TextView hint=text("先在手机本地识别顺序和重叠区域；不确定时保留内容，可手动拖动调整。",14,0xff65758b);hint.setPadding(0,dp(6),0,dp(10));card.addView(hint);
  TextView pick=text("＋  选择截图",17,0xff17334f);pick.setGravity(Gravity.CENTER);pick.setPadding(10,dp(12),10,dp(12));pick.setBackground(glass(0xffedf3fa,0xffdbe5f2));pick.setElevation(dp(4));card.addView(pick);pick.setOnClickListener(v->chooseImages());
  TextView ai=text("✨  AI 辅助排序（可选，长按设置密钥）",13,0xff225a9a);ai.setGravity(Gravity.CENTER);ai.setPadding(4,dp(10),4,dp(4));card.addView(ai);ai.setOnClickListener(v->aiSort());ai.setOnLongClickListener(v->{editKey();return true;});
  status=text("请选择 2 张以上同一页面连续滚动的截图",14,0xff43536b);status.setPadding(dp(2),dp(10),0,dp(2));root.addView(status);
  list=new LinearLayout(this);list.setOrientation(1);ScrollView scroll=new ScrollView(this);scroll.addView(list);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,0,1);lp.topMargin=dp(8);root.addView(scroll,lp);
  TextView preview=text("预览并生成长图  →",20,0xff124455);preview.setGravity(Gravity.CENTER);preview.setPadding(10,dp(14),10,dp(14));preview.setBackground(glass(0xffeaf4f5,0xffcedfe9));preview.setElevation(dp(7));preview.setMinHeight(dp(60));LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(-1,-2);pp.topMargin=dp(8);root.addView(preview,pp);preview.setOnClickListener(v->preview());
 }
 void chooseImages(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);i.addCategory(Intent.CATEGORY_OPENABLE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,1);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=1||result!=RESULT_OK||data==null)return;images.clear();try{if(data.getClipData()!=null){int count=Math.min(data.getClipData().getItemCount(),20);for(int n=0;n<count;n++)readImage(data.getClipData().getItemAt(n).getUri());}else if(data.getData()!=null)readImage(data.getData());}catch(Exception e){status.setText("有图片读取失败，请重新选择");}showRows();if(images.size()<2){status.setText("至少选择 2 张截图");return;}analyzeLocal();}
 void readImage(Uri uri)throws Exception{try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(in,null,bounds);}int sample=1;while(Math.max(bounds.outWidth/sample,bounds.outHeight/sample)>2200)sample*=2;BitmapFactory.Options opt=new BitmapFactory.Options();opt.inSampleSize=sample;try(InputStream in=getContentResolver().openInputStream(uri)){Bitmap b=BitmapFactory.decodeStream(in,null,opt);if(b!=null&&!duplicate(b))images.add(b);}}
 boolean duplicate(Bitmap b){for(Bitmap old:images){if(Math.abs((long)old.getWidth()*b.getHeight()-(long)b.getWidth()*old.getHeight())>Math.max(old.getWidth(),b.getWidth())*20L)continue;double diff=0;int n=0;for(int y=0;y<24;y++)for(int x=0;x<16;x++){int p=old.getPixel((x*old.getWidth())/16,(y*old.getHeight())/24),q=b.getPixel((x*b.getWidth())/16,(y*b.getHeight())/24);diff+=Math.abs(Color.red(p)-Color.red(q))+Math.abs(Color.green(p)-Color.green(q))+Math.abs(Color.blue(p)-Color.blue(q));n+=3;}if(diff/n<1.2)return true;}return false;}
 Match overlap(Bitmap a,Bitmap b){int h=Math.min(a.getHeight(),b.getHeight()),max=(int)(h*.68),min=Math.max(28,(int)(h*.035));if(max<=min)return new Match(0,99);double best=99;int bestCut=0;int step=Math.max(3,h/500);
  for(int k=min;k<=max;k+=step){double color=0,edges=0,energy=0;int n=0;for(int yy=0;yy<24;yy++){int dy=yy*(k-1)/23,ay=a.getHeight()-k+dy;for(int xx=2;xx<38;xx+=2){int ax=xx*a.getWidth()/40,bx=xx*b.getWidth()/40;int p=a.getPixel(ax,ay),q=b.getPixel(bx,dy);int gp=(Color.red(p)*3+Color.green(p)*6+Color.blue(p))/10,gq=(Color.red(q)*3+Color.green(q)*6+Color.blue(q))/10;color+=Math.abs(gp-gq);int ax1=Math.min(a.getWidth()-1,ax+Math.max(1,a.getWidth()/40)),bx1=Math.min(b.getWidth()-1,bx+Math.max(1,b.getWidth()/40));int p1=a.getPixel(ax1,ay),q1=b.getPixel(bx1,dy);int ep=(Color.red(p1)*3+Color.green(p1)*6+Color.blue(p1))/10-gp,eq=(Color.red(q1)*3+Color.green(q1)*6+Color.blue(q1))/10-gq;edges+=Math.abs(ep-eq);energy+=Math.abs(ep)+Math.abs(eq);n++;}}
   double texture=energy/n,score=color/n+edges/n*.75+1.2*k/(double)max;if(texture>1.4&&score<best){best=score;bestCut=k;}}
  return bestCut>0&&best<18?new Match(bestCut,best):new Match(0,best);
 }
 void analyzeLocal(){if(busy)return;busy=true;status.setText("正在手机本地分析截图…");new Thread(()->{int n=images.size();Match[][] m=new Match[n][n];double[][] weights=new double[n][n];for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(i!=j){m[i][j]=overlap(images.get(i),images.get(j));weights[i][j]=m[i][j].weight();}
  int first=0;double minIncoming=Double.MAX_VALUE;for(int j=0;j<n;j++){double in=0;for(int i=0;i<n;i++)if(i!=j)in+=weights[i][j];if(in<minIncoming){minIncoming=in;first=j;}}
  ArrayList<Bitmap> sorted=new ArrayList<>();boolean[] used=new boolean[n];sorted.add(images.get(first));used[first]=true;int cur=first;while(sorted.size()<n){int next=-1;double best=0;for(int j=0;j<n;j++)if(!used[j]&&weights[cur][j]>best){best=weights[cur][j];next=j;}if(next<0){double smallest=Double.MAX_VALUE;for(int j=0;j<n;j++)if(!used[j]){double in=0;for(int i=0;i<n;i++)if(!used[i]&&i!=j)in+=weights[i][j];if(in<smallest){smallest=in;next=j;}}}sorted.add(images.get(next));used[next]=true;cur=next;}
  runOnUiThread(()->{images.clear();images.addAll(sorted);busy=false;showRows();boolean any=false;for(double[] row:weights)for(double w:row)if(w>0)any=true;status.setText(any?"已完成本机排序估算；请看编号并拖动复核":"未找到可靠重叠，已保留当前顺序，请手动拖动调整");});
 }).start();}
 void showRows(){if(list==null)return;list.removeAllViews();for(int i=0;i<images.size();i++){final int ix=i;LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(8),dp(8),dp(8),dp(8));GradientDrawable bg=new GradientDrawable();bg.setColor(Color.WHITE);bg.setCornerRadius(dp(16));row.setBackground(bg);row.setTag(i);LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,dp(118));rp.bottomMargin=dp(8);row.setLayoutParams(rp);TextView num=text(String.format(Locale.getDefault(),"%02d",i+1),15,Color.WHITE);num.setGravity(Gravity.CENTER);GradientDrawable badge=new GradientDrawable();badge.setColor(0xff2563eb);badge.setCornerRadius(dp(15));num.setBackground(badge);row.addView(num,new LinearLayout.LayoutParams(dp(38),dp(38)));ImageView image=new ImageView(this);image.setImageBitmap(images.get(i));image.setScaleType(ImageView.ScaleType.CENTER_CROP);LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(0,dp(102),1);ip.setMargins(dp(10),0,dp(8),0);row.addView(image,ip);row.addView(text("☷",20,0xff728198));row.setOnLongClickListener(v->{ClipData cd=ClipData.newPlainText("index",String.valueOf(ix));if(Build.VERSION.SDK_INT>=24)v.startDragAndDrop(cd,new View.DragShadowBuilder(v),v,0);else v.startDrag(cd,new View.DragShadowBuilder(v),v,0);return true;});row.setOnDragListener((v,e)->{if(e.getAction()==DragEvent.ACTION_DROP){int from=Integer.parseInt(e.getClipData().getItemAt(0).getText().toString()),to=(int)v.getTag();if(from>=0&&from<images.size()&&to>=0&&to<images.size()){Bitmap move=images.remove(from);images.add(to,move);showRows();}return true;}return true;});list.addView(row);}if(!images.isEmpty())status.setText(images.size()+" 张截图 · 长按卡片可拖动排序");}
 Bitmap compose(){int w=images.get(0).getWidth();ArrayList<Bitmap> scaled=new ArrayList<>();for(Bitmap b:images)scaled.add(Bitmap.createScaledBitmap(b,w,Math.max(1,b.getHeight()*w/b.getWidth()),true));long height=0;ArrayList<Integer> cuts=new ArrayList<>();for(int i=0;i<scaled.size();i++){int cut=i==0?0:overlap(scaled.get(i-1),scaled.get(i)).cut;cuts.add(cut);height+=scaled.get(i).getHeight()-cut;}if(height>26000||(long)w*height>45000000L)throw new RuntimeException("长图过大，请分批生成");Bitmap result=Bitmap.createBitmap(w,(int)height,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(result);Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);int y=0;for(int i=0;i<scaled.size();i++){Bitmap b=scaled.get(i);int cut=cuts.get(i);canvas.drawBitmap(b,0,y-cut,paint);y+=b.getHeight()-cut;}return result;}
 void preview(){if(images.size()<2){status.setText("请先选择至少 2 张截图");return;}if(busy){status.setText("分析尚未完成，请稍等");return;}try{Bitmap result=compose();ImageView iv=new ImageView(this);iv.setImageBitmap(result);iv.setAdjustViewBounds(true);iv.setScaleType(ImageView.ScaleType.FIT_START);ScrollView sc=new ScrollView(this);sc.addView(iv);LinearLayout body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(12),dp(8),dp(12),dp(8));body.addView(text("拼接预览 · "+images.size()+" 张",16,0xff182230));body.addView(sc,new LinearLayout.LayoutParams(-1,0,1));new AlertDialog.Builder(this).setTitle("确认长图").setView(body).setNegativeButton("返回调整",null).setPositiveButton("确认并保存",(d,w)->save(result)).show();}catch(Exception e){status.setText("预览失败："+e.getMessage());}}
 void save(Bitmap image){try{ContentValues values=new ContentValues();values.put(MediaStore.Images.Media.DISPLAY_NAME,"长图_"+System.currentTimeMillis()+".jpg");values.put(MediaStore.Images.Media.MIME_TYPE,"image/jpeg");values.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/长图助手");Uri uri=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new Exception("无法创建相册文件");try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null||!image.compress(Bitmap.CompressFormat.JPEG,94,out))throw new Exception("图片写入失败");}status.setText("已保存到相册：Pictures/长图助手");}catch(Exception e){status.setText("保存失败："+e.getMessage());}}
 String getKey(){return getSharedPreferences("prefs",0).getString("gemini_key","");}
 void aiSort(){if(images.size()<2){status.setText("先选择截图，再使用 AI");return;}if(images.size()>8){status.setText("AI排序最多支持 8 张，请分批选择");return;}if(getKey().isEmpty()){editKey();return;}new AlertDialog.Builder(this).setTitle("AI辅助排序").setMessage("AI会将截图缩略图发送到 Google Gemini 判断上下文顺序。AI服务有免费额度限制，是否继续？").setNegativeButton("取消",null).setPositiveButton("继续",(d,w)->sendToAi()).show();}
 void editKey(){EditText input=new EditText(this);input.setSingleLine(true);input.setHint("粘贴 API 密钥");input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);input.setText(getKey());LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(20),dp(8),dp(20),0);box.addView(input);box.addView(text("在 Google AI Studio 可创建免费层 API 密钥。密钥保存在本机应用设置中。",13,0xff526179));new AlertDialog.Builder(this).setTitle("设置 Gemini 免费 AI").setView(box).setNeutralButton("打开 AI Studio",(d,w)->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://aistudio.google.com/app/apikey")));}catch(Exception ignored){}}).setNegativeButton("取消",null).setPositiveButton("保存",(d,w)->{getSharedPreferences("prefs",0).edit().putString("gemini_key",input.getText().toString().trim()).apply();status.setText("AI密钥已保存；再次点击AI辅助排序即可使用");}).show();}
 void sendToAi(){if(busy)return;busy=true;status.setText("正在发送缩略图并请求 AI 排序…");new Thread(()->{try{JSONArray parts=new JSONArray();parts.put(new JSONObject().put("text","请按截图内容的上下文将这些连续页面截图从上到下排序。每张图前面有输入序号。只输出JSON，格式{\"order\":[2,1,3]}，序号从1开始，每个输入序号恰好出现一次。"));for(int i=0;i<images.size();i++){parts.put(new JSONObject().put("text","截图输入序号 "+(i+1)));Bitmap original=images.get(i);float scale=Math.min(1f,320f/Math.max(original.getWidth(),original.getHeight()));Bitmap thumb=Bitmap.createScaledBitmap(original,Math.max(1,(int)(original.getWidth()*scale)),Math.max(1,(int)(original.getHeight()*scale)),true);ByteArrayOutputStream bytes=new ByteArrayOutputStream();thumb.compress(Bitmap.CompressFormat.JPEG,60,bytes);parts.put(new JSONObject().put("inline_data",new JSONObject().put("mime_type","image/jpeg").put("data",android.util.Base64.encodeToString(bytes.toByteArray(),android.util.Base64.NO_WRAP))));if(thumb!=original)thumb.recycle();}
   JSONObject body=new JSONObject().put("contents",new JSONArray().put(new JSONObject().put("parts",parts))).put("generationConfig",new JSONObject().put("temperature",0).put("responseMimeType","application/json"));HttpURLConnection conn=(HttpURLConnection)new URL("https://generativelanguage.googleapis.com/v1beta/models/gemini-3.8-flash:generateContent").openConnection();conn.setRequestMethod("POST");conn.setConnectTimeout(20000);conn.setReadTimeout(45000);conn.setDoOutput(true);conn.setRequestProperty("Content-Type","application/json");conn.setRequestProperty("x-goog-api-key",getKey());try(OutputStream out=conn.getOutputStream()){out.write(body.toString().getBytes("UTF-8"));}int code=conn.getResponseCode();InputStream response=code>=200&&code<300?conn.getInputStream():conn.getErrorStream();String raw=readAll(response);conn.disconnect();if(code<200||code>=300)throw new Exception("AI接口 "+code+"："+raw.substring(0,Math.min(raw.length(),160)));String answer=new JSONObject(raw).getJSONArray("candidates").getJSONObject(0).getJSONObject("content").getJSONArray("parts").getJSONObject(0).getString("text").trim();int l=answer.indexOf('{'),r=answer.lastIndexOf('}');if(l<0||r<=l)throw new Exception("AI没有返回可读的顺序");JSONArray order=new JSONObject(answer.substring(l,r+1)).getJSONArray("order");if(order.length()!=images.size())throw new Exception("AI返回项目数量不匹配");ArrayList<Bitmap> sorted=new ArrayList<>();boolean[] used=new boolean[images.size()];for(int i=0;i<order.length();i++){int k=order.getInt(i)-1;if(k<0||k>=images.size()||used[k])throw new Exception("AI返回的序号无效");used[k]=true;sorted.add(images.get(k));}
   runOnUiThread(()->{images.clear();images.addAll(sorted);busy=false;showRows();status.setText("AI排序完成，请检查编号并手动复核");});
  }catch(Exception e){runOnUiThread(()->{busy=false;status.setText("AI未能连接；本机拼接仍可用："+e.getMessage());});}}).start();}
 String readAll(InputStream in)throws Exception{if(in==null)return "";try(InputStream source=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[4096];int n;while((n=source.read(buf))!=-1)out.write(buf,0,n);return new String(out.toByteArray(),"UTF-8");}
 }
